from taf.gnb.oam.ne3s.ws.components.connection.messages import (
    NotificationMsg, NotificationType, AttachmentType, NotificationGroup)


class UMOperationNotification(NotificationMsg):
    @staticmethod
    def matches(soap, attachment):
        return (isinstance(soap, NotificationType.ReportOperationStatus)
                and isinstance(attachment, AttachmentType.Feedback)
                and attachment.get_managed_objects_for_class("USERACCOUNT"))


class UMNotificationGroup(NotificationGroup):
    QUEUE_IDS = ("common_queue", )
    NOTIFICATIONS = (UMOperationNotification, )
